 $viEvent=$viAdmin->open($viSource,$key());$viAdmin->grant($viEvent,[$viPerson],[['label'=>'0','kind'=>'other','unit'=>'piece','amount'=>$viIndex===0?'30':'1'],['label'=>'Own human EUR label ä🙂','kind'=>'other','unit'=>'eur','amount'=>'3.50']],$key());
